@Label("Move all the negative elements to one side of the array ")
class Solution_5 {

    @Description("Partition Method")
    public long modifyArray(int[] arr, int n) {
        long start = System.nanoTime();
        int j = 0;
        for (int i = 0; i < n; i++) {
            if (arr[i] < 0) {
                if (i != j)
                    arr[i] = arr[i] ^ arr[j] ^ (arr[j] = arr[i]);
                j++;
            }
        }
        long end = System.nanoTime();
        long execution = end - start;
        return execution;
    }

    @Description("Two Pointer Approach")
    public long modifyArray2(int[] arr, int n) {
        long star = System.nanoTime();
        int start = 0, end = n - 1;
        while (start <= end) {
            if (arr[start] < 0 && arr[end] < 0) {
                start++;
            } else if (arr[end] < 0 && arr[start] >= 0) {
                arr[start] = arr[start] ^ arr[end] ^ (arr[end] = arr[start]);
                start++;
                end--;
            } else if (arr[end] >= 0 && arr[start] >= 0) {
                end--;
            } else {
                start++;
                end--;
            }
        }
        long en = System.nanoTime();
        long execution = en - star;
        return execution;
    }

    @Description("Using Hash Map")
    public long modifyArray3(int[] arr, int n) {
        long start = System.nanoTime();
        Map<Character, List<Integer>> map = new HashMap<>();
        for (int i : arr) {
            if (i < 0)
                map.computeIfAbsent('-', x -> new ArrayList<>()).add(i);
            else
                map.computeIfAbsent('+', x -> new ArrayList<>()).add(i);
        }
        int i = 0;

        List<Integer> list = map.get('-');
        for (Integer integer : list) {
            arr[i++] = integer;
        }

        list = map.get('+');
        for (Integer integer : list) {
            arr[i++] = integer;
        }
        long end = System.nanoTime();
        long execution = end - start;
        return execution;
    }

}
